   if(step<0||studio.click){if(sub%2===0)click(time,sub===0);}
   const chordChange=sub>0&&chordAtSubdivision(b.chord,sub)!==chordAtSubdivision(b.chord,sub-1);
   if(step>=0&&studio.backing&&(PATTERNS[studio.pattern].hits.includes(sub)||chordChange))soundChord(chordAtSubdivision(b.chord,sub),time,studio.transpose,PATTERNS[studio.pattern].display[sub]==='↑');
