function stopTuner(){tunerGeneration++;cancelAnimationFrame(tunerFrame);tunerStream?.getTracks().forEach(t=>t.stop());tunerSource?.disconnect();tunerSource=null;tunerStream=null;tunerFrame=null;}
async function listen(){
 if(tunerStream){stopTuner();$('#listen-button').innerHTML=icon('headphones')+' Start listening';$('#tuner-feedback').textContent='Microphone stopped.';return;}
 const generation=++tunerGeneration;const btn=$('#listen-button');btn.disabled=true;btn.textContent='Requesting microphone…';
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw Error('Microphone tuning needs HTTPS or localhost. Use reference tones here.');
  await getAudio();const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});
  if(view!=='tuner'||generation!==tunerGeneration){stream.getTracks().forEach(t=>t.stop());return;}
  tunerStream=stream;const analyser=audio.createAnalyser();analyser.fftSize=2048;tunerSource=audio.createMediaStreamSource(stream);tunerSource.connect(analyser);
  const samples=new Float32Array(analyser.fftSize);let last=0,history=[];
  $('#listen-button').disabled=false;$('#listen-button').innerHTML=icon('pause')+' Stop listening';
  const frame=time=>{if(!tunerStream||view!=='tuner')return;if(time-last>120){last=time;analyser.getFloatTimeDomainData(samples);const pitch=detectPitch(samples,audio.sampleRate),target=tuning[tuneString];if(pitch){history.push(pitch);if(history.length>5)history.shift();const sorted=[...history].sort((a,b)=>a-b),f=sorted[Math.floor(sorted.length/2)],cents=1200*Math.log2(f/target.frequency);$('#tuner-frequency').textContent=`${f.toFixed(1)} Hz · ${cents>0?'+':''}${Math.round(cents)} cents`;$('#tuner-needle').style.left=`${50+Math.max(-50,Math.min(50,cents))}%`;$('#tuner-feedback').textContent=Math.abs(cents)<8?'In tune. Let it ring.':Math.abs(cents)>100?'Match the reference tone first; this string is far from its target.':cents<0?'A little low · tighten gently.':'A little high · loosen gently.';}else{history=[];$('#tuner-frequency').textContent=`Target ${target.frequency.toFixed(1)} Hz`;$('#tuner-feedback').textContent='Pluck the selected open string and let it ring.';$('#tuner-needle').style.left='50%';}}tunerFrame=requestAnimationFrame(frame);};tunerFrame=requestAnimationFrame(frame);
 }catch(err){if(view==='tuner'&&generation===tunerGeneration){$('#listen-button').disabled=false;$('#listen-button').innerHTML=icon('headphones')+' Start listening';$('#tuner-feedback').textContent=err.name==='NotAllowedError'?'Microphone permission was declined. You can still tune by reference tone.':err.name==='NotFoundError'?'No microphone was found. Use the reference tones.':err.message;}}
}
